/** Browser-only Manual Issuance administration layout fixture. */
$state = getenv( 'CERTLOOM_MANUAL_ISSUANCE_STATE' );
if ( ! in_array( $state, array( 'compose', 'review', 'receipt' ), true ) ) { $state = 'compose'; }
$css = file_get_contents( dirname( __DIR__, 2 ) . '/admin/assets/admin.css' );
function h( $value ) { return htmlspecialchars( (string) $value, ENT_QUOTES, 'UTF-8' ); }
function steps( $current ) {
	$items = array( 'compose' => 'Compose', 'review' => 'Review', 'issue' => 'Issue', 'receipt' => 'Receipt' );
	$seen = true;
	echo '<ol class="certloom-manual-steps" aria-label="Manual Issuance progress">';
	foreach ( $items as $key => $label ) {
		$class = $key === $current ? 'is-current' : ( $seen ? 'is-complete' : '' );
		echo '<li class="' . h( $class ) . '"' . ( $key === $current ? ' aria-current="step"' : '' ) . '><span>' . h( $label ) . '</span></li>';
		if ( $key === $current ) { $seen = false; }
	}
	echo '</ol>';
}
